const names=()=>Object.fromEntries((catalog?.skills||[]).map(s=>[s.id,s.name]));
function editorRequest(){return {title:el('title').value,source:el('source').value,steps:structuredClone(steps)}}
function collectInvalid(){const values={};for(const input of document.querySelectorAll('[data-draft-field]'))if(!input.validity.valid)values[input.dataset.draftField]={value:input.value,error:input.validationMessage};return values}
function restoreInvalid(){for(const input of document.querySelectorAll('[data-draft-field]')){const saved=invalidInputs[input.dataset.draftField];if(saved){input.value=saved.value;input.setCustomValidity(saved.error)}}}
