 invalidInputs=value.invalid||{};restoreInvalid();el('apply-caption').textContent=ref?'应用到当前片段':'添加字幕';el('delete-cue').disabled=!ref;el('split-cue').disabled=!ref;
 el('timeline-zoom').value=value.zoom||1;el('timeline-content').style.width=100*Number(el('timeline-zoom').value)+'%';el('media-search').value=value.search||'';mediaFilter=value.filter||'all';
 for(const b of document.querySelectorAll('[data-media]'))b.setAttribute('aria-pressed',String(b.dataset.media===mediaFilter));
