function persist(){clearTimeout(persistTimer);if(!initialized||storageBlocked)return;try{State.write(StudioStorage.local,localKey,{...captureEditor(),undo:undoState});localSaved=true;el('local-state').textContent='本机编辑已保存';el('local-retry').hidden=true}catch(e){localSaved=false;storageBlocked=true;el('local-state').textContent='本机保存失败，请下载恢复文件：'+e.message;el('local-retry').hidden=false}}
