el('undo-plan').onclick=()=>{if(!undoState)return;const previous=undoState,current=captureEditor();restoreEditor(previous);undoState=current;const project=draftId||job;history.replaceState(null,'','/video-tools'+(project?'?project='+project:''));localKey='ai-video-sequence-v1-'+(friend?'friend':'full')+'-'+(project||'scratch');if(job&&resultData?.id!==job){resultData=null;poll()}const item=mediaItems.find(i=>samePath(i.absolute_path,el('source').value));if(previewMode==='source'){if(item)previewSource(item);else clearResultPreview()}else if(resultData)showResult();changed();note('已恢复替换前的编辑内容；再点一次可切回。')};
el('download-recovery').onclick=()=>{let previous=null;try{previous=StudioStorage.local.getItem(localKey)}catch{}const blob=new Blob([JSON.stringify({version:1,...captureEditor(),undo:undoState,previous},null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='video-editor-recovery.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
