el('recovery-file').onchange=async()=>{const file=el('recovery-file').files[0],epoch=editEpoch;if(!file)return;try{if(file.size>5*1024*1024)throw Error('恢复文件超过 5 MB');const value=JSON.parse(await file.text());State.check(value.request,{empty:true});if(value.version!==1)throw Error('恢复文件版本不支持');if(epoch!==editEpoch)throw Error('读取期间已有新编辑，请重新选择恢复文件');checkpoint();restoreEditor(value);const project=draftId||job;history.replaceState(null,'','/video-tools'+(project?'?project='+encodeURIComponent(project):''));localKey='ai-video-sequence-v1-'+(friend?'friend':'full')+'-'+(project||'scratch');resultData=null;clearResultPreview();changed();if(job)await poll();note('已恢复文件中的编辑内容，尚未写入工程；可撤销此次恢复。')}catch(e){note('恢复失败：'+e.message)}finally{el('recovery-file').value=''}};
