async function api(path,data){const response=await fetch(path,data===undefined?{signal:AbortSignal.timeout(15000)}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await response.json();if(!response.ok)throw Error(value.error||'请求失败');return value}
function note(text){el('message').textContent=text;const dialog=document.querySelector('dialog[open]');if(dialog){let status=dialog.querySelector('.dialog-message');if(!status){status=document.createElement('p');status.className='dialog-message hint';status.setAttribute('role','status');dialog.querySelector('.dialog-heading').after(status)}status.textContent=text}}
function field(host,label,value,change,{type='text',options,wide=false,placeholder=''}={}){const wrap=document.createElement('label');wrap.textContent=label;if(wide)wrap.className='wide';const input=document.createElement(options?'select':type==='textarea'?'textarea':'input');if(options)for(const [v,t]of options){const o=new Option(t,v);if(friend&&['local','qwen','whisperx'].includes(v))o.disabled=true;input.append(o)}else if(type!=='textarea')input.type=type;if(type==='number')input.step='any';input.value=value??'';input.placeholder=placeholder;input.dataset.draftField=fieldContext+':'+label;input.addEventListener(options?'change':'input',()=>{input.setCustomValidity('');try{if(type==='number'&&(!input.value.trim()||!Number.isFinite(Number(input.value))))throw Error(label+' 应填写数字');change(type==='number'?Number(input.value):input.value);input.setCustomValidity('')}catch(e){input.setCustomValidity(e.message);note(e.message)}changed()});wrap.append(input);host.append(wrap);return input}
function text(host,label,opts,key,wide=false,placeholder=''){return field(host,label,opts[key],v=>opts[key]=v,{wide,placeholder})}
function select(host,label,opts,key,options){return field(host,label,opts[key]??options[0][0],v=>opts[key]=v,{options})}
