function drawMedia(){const query=el('media-search').value.trim().toLocaleLowerCase(),list=el('media-list');list.replaceChildren();const items=mediaItems.filter(i=>(mediaFilter==='all'||i.media_type===mediaFilter)&&i.title.toLocaleLowerCase().includes(query));if(!items.length){const p=document.createElement('p');p.className='hint';p.textContent=query?'没有匹配的素材，试试其他关键词。':'这里还没有素材。添加本机素材，或先制作一部作品。';list.append(p);return}for(const item of items){const b=document.createElement('button');b.className='media-card';b.setAttribute('aria-pressed',String(item.absolute_path===el('source').value));b.setAttribute('aria-label','使用素材：'+item.title);let thumb;if(item.thumbnail_url){thumb=document.createElement('img');thumb.src=item.thumbnail_url;thumb.alt='';thumb.loading='lazy'}else{thumb=document.createElement('video');thumb.src=item.preview_url;thumb.muted=true;thumb.preload='metadata';thumb.setAttribute('aria-hidden','true')}thumb.className='thumb';const copy=document.createElement('span'),name=document.createElement('strong'),meta=document.createElement('small');name.textContent=item.title;meta.textContent=(item.media_type==='video'?'视频':'图片')+(item.duration?' · '+clock(item.duration):'');copy.append(name,meta);b.append(thumb,copy);b.onclick=()=>{if(!validFields())return;el('source').value=item.absolute_path;el('assets').value=item.absolute_path;changed();previewSource(item);drawMedia();note('已选用素材；点击“制作视频”生成新版本。')};list.append(b)}}
el('media-search').oninput=()=>{drawMedia();schedulePersist()};for(const b of document.querySelectorAll('[data-media]'))b.onclick=()=>{mediaFilter=b.dataset.media;for(const other of document.querySelectorAll('[data-media]'))other.setAttribute('aria-pressed',other===b);drawMedia();schedulePersist()};
function selectCue(row){try{flushQuick()}catch(e){note(e.message);return}selectedCue={si:row.si,index:row.index,key:row.key,ref:row.cue};el('quick-caption').value=row.cue.text;el('cue-start').value=row.cue.start;el('cue-end').value=row.cue.end;el('apply-caption').textContent='应用到当前片段';el('delete-cue').disabled=false;el('split-cue').disabled=false;selectTab('caption');seek(row.cue.start);drawTimeline()}
function clip(track,label,start,end,className,action){const b=document.createElement('button');b.className='track-clip '+className;b.textContent=label;b.title=label+' · '+clock(start)+'–'+clock(end);b.style.left=(Math.min(duration(),Math.max(0,start))/duration()*100)+'%';b.style.width=(Math.max(.01,Math.min(end,duration())-Math.max(0,start))/duration()*100)+'%';b.onclick=action;el(track).append(b);return b}
function drawTimeline(){if(!el('time-ruler'))return;const selected=currentCue();if(selected)selectedCue={...selectedCue,si:selected.si,index:selected.index,key:selected.key};else if(selectedCue){selectedCue=null;el('apply-caption').textContent='添加字幕';el('delete-cue').disabled=true;el('split-cue').disabled=true}const total=duration();el('time-ruler').replaceChildren();const ticks=Math.max(2,Math.min(10,Math.floor(el('time-ruler').clientWidth/80)));for(let i=0;i<=ticks;i++){const tick=document.createElement('span');tick.textContent=total<20?(total*i/ticks).toFixed(1)+'s':clock(total*i/ticks);tick.style.left=(i/ticks*100)+'%';if(i===ticks)tick.style.transform='translateX(-100%)';el('time-ruler').append(tick)}for(const id of ['visual-track','voice-track','caption-track'])el(id).replaceChildren();const visual=steps.find(s=>['remotion','hyperframes','browser-video-recording'].includes(s.skill));if(el('source').value||visual||!el('video').hidden)clip('visual-track',visual?(visual.options.props?.title||({'remotion':'动效画面','hyperframes':'动效视频','browser-video-recording':'网页演示'}[visual.skill])||'画面'):sourcePreview?.title||'当前素材',0,total,'active',()=>{selectTab('plan')});else{el('visual-track').innerHTML='<span class="track-empty">选择素材或添加一个视频生成步骤</span>'}const voice=steps.find(s=>['app-demo-agent','video-dubbing'].includes(s.skill));if(voice)clip('voice-track',voice.options.narration||'配音 · '+(voice.options.voice||'默认音色'),0,total,'voice-clip',()=>selectTab('voice'));else el('voice-track').innerHTML='<span class="track-empty">尚未添加配音 · 在上方“配音”中编写旁白</span>';for(const row of cues())clip('caption-track',row.cue.text||'未填写字幕',Number(row.cue.start),Math.min(total,Number(row.cue.end)),'caption-clip'+(selectedCue?.si===row.si&&selectedCue?.index===row.index&&selectedCue?.key===row.key?' active':''),()=>selectCue(row));if(!cues().length)el('caption-track').innerHTML='<span class="track-empty">添加字幕后，将在这里显示对应时间段</span>';el('plan-chips').replaceChildren();steps.forEach((s,i)=>smallButton(el('plan-chips'),(i+1)+' · '+({'hyperframes':'动效视频','remotion':'模板视频','video-use':'内容剪辑','ffmpeg-skill':'画幅与剪辑','agent-caption':'字幕','video-subtitle-translator':'字幕翻译','video-dubbing':'多语言配音','app-demo-agent':'产品配音','browser-video-recording':'网页演示','imagegen':'视觉素材'}[s.skill]||s.skill),()=>{showDialog('settings-dialog');el('steps').children[i]?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}));position(playTime)}
el('timeline-zoom').oninput=()=>{schedulePersist();el('timeline-content').style.width=(100*Number(el('timeline-zoom').value))+'%';drawTimeline()};el('fit-timeline').onclick=()=>{el('timeline-zoom').value=1;el('timeline-content').style.width='100%'};
el('apply-caption').onclick=()=>{const start=el('cue-start').value.trim()?Number(el('cue-start').value):NaN,end=el('cue-end').value.trim()?Number(el('cue-end').value):NaN,text=el('quick-caption').value.trim();if(!text||!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start){note('请填写字幕内容，并确保结束时间晚于开始时间。');return}let row=currentCue();if(row){Object.assign(row.cue,{start,end,text});const o=steps[row.si].options;const paired=row.key==='cues'?'translated_cues':'cues';if(o[paired]?.[row.index])Object.assign(o[paired][row.index],{start,end})}else{let si=steps.findIndex(s=>s.skill==='agent-caption');if(si<0){if(steps.length>=12){note('最多可添加 12 个制作步骤。');return}steps.push({skill:'agent-caption',options:structuredClone(defaults['agent-caption'])});si=steps.length-1}const o=steps[si].options;o.cues=o.cues||[];o.cues.push({start,end,text});selectedCue={si,index:o.cues.length-1,key:'cues',ref:o.cues[o.cues.length-1]}}pendingCaption=false;changed();render();el('apply-caption').textContent='应用到当前片段';el('delete-cue').disabled=false;el('split-cue').disabled=false;note('字幕已应用到方案，下次制作时生效。')};
el('delete-cue').onclick=()=>{pendingCaption=false;const row=currentCue();if(!row)return;steps[row.si].options[row.key].splice(row.index,1);const paired=row.key==='cues'?'translated_cues':'cues';if(steps[row.si].options[paired])steps[row.si].options[paired].splice(row.index,1);selectedCue=null;el('quick-caption').value='';el('apply-caption').textContent='添加字幕';el('delete-cue').disabled=true;el('split-cue').disabled=true;changed();render();note('字幕段已从方案移除。')};
el('split-cue').onclick=()=>{try{flushQuick()}catch(e){note(e.message);return}const row=currentCue();if(!row)return;const at=Number(playTime.toFixed(2));if(at<=row.cue.start+.05||at>=row.cue.end-.05){note('先将播放位置移动到当前字幕段内，再分割。');return}const o=steps[row.si].options,oldEnd=row.cue.end;row.cue.end=at;o[row.key].splice(row.index+1,0,{...row.cue,start:at,end:oldEnd});const paired=row.key==='cues'?'translated_cues':'cues';if(o[paired]?.[row.index]){const other=o[paired][row.index],end=other.end;other.end=at;o[paired].splice(row.index+1,0,{...other,start:at,end})}el('cue-end').value=at;changed();render();note('已按当前播放位置分割字幕，可分别修改两段文字。')};
function syncVoice(){if(pendingNarration)return;invalidInputs=collectInvalid();fieldContext='quick-voice';const s=steps.find(s=>['app-demo-agent','video-dubbing'].includes(s.skill));el('quick-narration').value=s?.options.narration||'';el('quick-narration').disabled=s?.skill==='video-dubbing';el('apply-voice').textContent=s?.skill==='video-dubbing'?'编辑多语言配音':'应用配音';el('quick-voice-options').replaceChildren();if(s)voiceEditor(el('quick-voice-options'),s.options);restoreInvalid()}
el('apply-voice').onclick=()=>{let s=steps.find(s=>['app-demo-agent','video-dubbing'].includes(s.skill));if(s?.skill==='video-dubbing'){showDialog('settings-dialog');return}const narration=el('quick-narration').value.trim();if(!narration){note('先填写旁白内容。');return}if(!s){if(steps.length>=12){note('最多可添加 12 个制作步骤。');return}s={skill:'app-demo-agent',options:structuredClone(defaults['app-demo-agent'])};steps.push(s)}s.options.narration=narration;pendingNarration=false;changed();render();syncVoice();note('旁白已加入方案，制作时使用所选音色生成。')};
